-- (a)
CREATE TABLE Branch (
  branch_name VARCHAR(30) PRIMARY KEY,
  branch_city VARCHAR(30) NOT NULL,
  assets      NUMERIC(16,2)
);
CREATE TABLE Account (
  acc_name    VARCHAR(10) PRIMARY KEY,
  balance     NUMERIC(14,2) NOT NULL,
  branch_name VARCHAR(30) NOT NULL REFERENCES Branch(branch_name)
);
INSERT INTO Branch  SELECT DISTINCT branch_name, branch_city, assets FROM Bank_Flat;
INSERT INTO Account SELECT acc_name, balance, branch_name FROM Bank_Flat;
-- Branch gets 2 rows (Motijheel, Agrabad); Account gets 3 rows.

-- (b) lossless: the join equals the original in both directions
SELECT COUNT(*) FROM (
  (SELECT a.acc_name, a.balance, b.branch_name, b.branch_city, b.assets
     FROM Account a JOIN Branch b ON a.branch_name = b.branch_name
   EXCEPT SELECT * FROM Bank_Flat)
  UNION ALL
  (SELECT * FROM Bank_Flat
   EXCEPT SELECT a.acc_name, a.balance, b.branch_name, b.branch_city, b.assets
     FROM Account a JOIN Branch b ON a.branch_name = b.branch_name)
) diff;
-- Output: 0  (no missing and no spurious rows)

-- (c) update anomaly in the old table
UPDATE Bank_Flat SET branch_city = 'Narayanganj' WHERE acc_name = 'A-101';
SELECT DISTINCT branch_name, branch_city FROM Bank_Flat WHERE branch_name = 'Motijheel';
-- Output: 2 rows (Motijheel | Dhaka) and (Motijheel | Narayanganj): the copies now disagree.

-- In the new design the city is stored once:
UPDATE Branch SET branch_city = 'Narayanganj' WHERE branch_name = 'Motijheel';
-- one row changes, and every Motijheel account sees the new city through the join.

The split works because branch_name → branch_city, assets and branch_name is the key of Branch, so the common attribute of the two tables is a key of one of them.

